const carousel = document.querySelector('[data-card-slot="carousel"]');
if (!carousel) {
  JSON.stringify({found: false});
} else {
  const cs = getComputedStyle(carousel);
  JSON.stringify({
    found: true,
    display: cs.display,
    outerHTML_start: carousel.outerHTML.slice(0, 200),
  });
}

const carousel = document.querySelector('[data-card-slot="carousel"]');
const matches = [];
for (const sheet of document.styleSheets) {
  let rules;
  try { rules = sheet.cssRules; } catch(e) { continue; }
  for (const rule of rules) {
    if (rule.selectorText && carousel.matches(rule.selectorText.split(',')[0].trim())) {
      matches.push({selector: rule.selectorText, css: rule.style.cssText});
    }
    if (rule.media && rule.cssRules) {
      for (const inner of rule.cssRules) {
        if (inner.selectorText && carousel.matches(inner.selectorText.split(',')[0].trim())) {
          matches.push({media: rule.media.mediaText, selector: inner.selectorText, css: inner.style.cssText});
        }
      }
    }
  }
}
JSON.stringify({
  hoverMediaMatches: window.matchMedia('(hover: hover) and (pointer: fine)').matches,
  matches,
}, null, 2);

