const carousel = document.querySelector('[data-card-slot="carousel"]');
JSON.stringify({
  found: !!carousel,
  displayAtRest: carousel && getComputedStyle(carousel).display,
});

const scrollContainer = document.querySelector('[data-testid="card-media-scroll"]');
scrollContainer.focus();
const carousel = document.querySelector('[data-card-slot="carousel"]');
JSON.stringify({
  activeElement: document.activeElement === scrollContainer,
  carouselDisplayAfterFocus: getComputedStyle(carousel).display,
});

document.activeElement.blur();
const carousel = document.querySelector('[data-card-slot="carousel"]');
JSON.stringify({ carouselDisplayAfterBlur: getComputedStyle(carousel).display });

