/** A full image gallery — desktop shows prev/next arrows, touch shows the slide indicator
 *  instead; native scroll-snap paging works on every pointer type regardless. */
export const MultipleImages: Story = {
  args: {
    primaryImage: PRIMARY_IMAGE,
    images: GALLERY_IMAGES,
    swapOnHover: false,
    showControls: true,
  },
  // No `play`: the arrows this story renders are visually/interactively gated by the recipe's
  // own `(hover: hover) and (pointer: fine)` media query, and there is no Storybook API to force
  // that media context per-story — a play function here would depend on whatever pointer
  // capability the executing environment happens to report, rather than proving anything about
  // this component. The click → scrollTo("plausible shape") contract is proven deterministically
  // in index.test.tsx instead, where the mock DOM node is controlled directly.
};

/** Wishlist context — the remove (close) button, wired to a callback logged via `fn()`. */
export const WithRemoveButton: Story = {
  name: 'With remove button (wishlist)',
  args: {
    primaryImage: PRIMARY_IMAGE,
    swapOnHover: false,
    showControls: false,
    onRemove: fn(),
    removeLabel: 'Remove Zimmermann silk midi dress from wishlist',
  },
};

/** PLP/Wishlist context — the merchandiser badge label, top-left of the image. Home never
 *  passes this (see the organism's own VARIATION_CONFIG.showBadge). */
export const WithBadge: Story = {
  name: 'With badge (PLP/Wishlist)',
  args: {
    primaryImage: PRIMARY_IMAGE,
    swapOnHover: false,
    showControls: false,
    badge: 'Runway',
  },
};

/** Explicit single-image case — no arrows, no indicator, no horizontal overflow, even though
 *  `showControls` is requested (there is nothing to page through). */
export const SingleImage: Story = {
  args: {
    primaryImage: PRIMARY_IMAGE,
    swapOnHover: false,
    showControls: true,
  },
};

