/**
 * Fix 1 (Scorer round 1, SFCC-236 Step 4 rework): the 19 tests above all render through the
 * `vi.mock('@chakra-ui/react', ...)` at the top of this file, which replaces useMultiStyleConfig
 * with a flat `{}` return for every part — none of them ever evaluate the REAL recipe object.
 * Proved live by the Scorer: deleting the recipe's HOVER_CAPABLE_QUERY media-query gate entirely
 * (making the desktop arrows permanently visible regardless of pointer capability) left the
 * whole suite green. These tests import the recipe module directly and call its exported
 * baseStyle(), bypassing the mock entirely — same technique as
 * zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts.
 *
 * Fix 2 (live-verified in a real browser, not this mock, post-SFCC-236 merge): the assertion
 * this Fix 1 comment describes only ever guarded against the gate being deleted outright — it
 * asserted `carousel[HOVER_CAPABLE_QUERY].display === 'flex'` directly, which is itself the
 * shape of a real, shipped bug: a hover-CAPABLE device (any desktop/laptop, confirmed via
 * `window.matchMedia`) showed the arrows permanently, with no requirement that the user actually
 * be hovering. Confirmed against a fresh page load with zero mouse interaction — `carousel`'s
 * computed `display` was already `flex`. The reveal now lives on `root` as an
 * `&:hover [data-card-slot="carousel"], &:focus-within [...]` selector nested inside
 * `HOVER_CAPABLE_QUERY` (same shape as `slide`'s own `&:hover [data-role="hover-overlay"]` above,
 * and the organism's root-level price/size-chip toggle) — `carousel` itself keeps only the
 * unconditional `display: 'none'` base state.
 */
describe('ZimmProductCardMedia — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  test('carousel (arrows) stays hidden by device capability alone — only an actual hover/focus on root reveals it', () => {
    const style = ZimmProductCardMediaRecipe.baseStyle();

    // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows hidden.
    expect(style.indicatorWrapper.display).toBe('block');
    expect(style.carousel.display).toBe('none');

    // Hover-capable pointers alone must NOT flip carousel to visible — that was the bug. `carousel`
    // carries no direct HOVER_CAPABLE_QUERY override of its own any more; the reveal is anchored on
    // `root` instead, gated on real `:hover`/`:focus-within`, not mere device capability.
    expect(style.carousel[HOVER_CAPABLE_QUERY]).toBeUndefined();

    const root = style.root as Record<string, unknown>;
    const rootHoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    const revealSelector = `&:hover [data-card-slot="${CARD_SLOT.carousel}"], &:focus-within [data-card-slot="${CARD_SLOT.carousel}"]`;
    const carouselReveal = rootHoverBlock[revealSelector] as Record<string, unknown>;

    expect(carouselReveal).toBeDefined();
    expect(carouselReveal.display).toBe('flex');

    // indicatorWrapper's own hover-capable-only hide is unaffected by this fix — its visibility
    // is purely device-capability-based (touch shows dots, desktop never does, regardless of
    // hover), not hover-state-based, so it still lives directly on indicatorWrapper.
    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect(indicatorHoverBlock.display).toBe('none');
  });

